140		_, _, err = store.CreateReservation(ctx, id, "res-1", 40)
141		wantCode(t, err, CodeReservationParamChanged)
142		view, _ = store.GetView(ctx, id)
143		if view.ReservedAmount != 30 {
144			t.Fatalf("param mismatch changed state: %+v", view)
145		}
146	}
