246	func TestConcurrentReservationsNeverExceedQuota(t *testing.T) {
247		store := testStore(t)
248		from, to := activeWindow()
249		id := uniqueID(t)
250		const quota = 100
251		mustCreate(t, store, id, quota, from, to)
252		ctx := context.Background()
253	
254		const workers = 16
255		var wg sync.WaitGroup
256		errs := make(chan error, workers*4)
257		for w := 0; w < workers; w++ {
258			wg.Add(1)
259			go func(w int) {
260				defer wg.Done()
261				for i := 0; i < 4; i++ {
262					rid := fmt.Sprintf("res-%d-%d", w, i)
263					if _, _, err := store.CreateReservation(ctx, id, rid, 10); err != nil {
264						errs <- err
265						continue
266					}
267					// Mix confirmations and releases into the race.
268					if i%2 == 0 {
269						_, _ = store.SettleReservation(ctx, id, rid, ActionConfirm)
270					} else {
271						_, _ = store.SettleReservation(ctx, id, rid, ActionRelease)
272					}
273				}
274			}(w)
275		}
276		wg.Wait()
277		close(errs)
278		for err := range errs {
279			var domainErr *Error
280			if !errors.As(err, &domainErr) || domainErr.Code != CodeInsufficientQuota {
281				t.Fatalf("unexpected concurrent failure: %v", err)
282			}
283		}
284		view, err := store.GetView(ctx, id)
285		if err != nil {
286			t.Fatalf("view: %v", err)
287		}
288		if view.UsedAmount+view.ReservedAmount > quota {
289			t.Fatalf("invariant violated: used=%d reserved=%d quota=%d",
290				view.UsedAmount, view.ReservedAmount, quota)
291		}
292		if view.AvailableAmount != quota-view.UsedAmount-view.ReservedAmount {
293			t.Fatalf("inconsistent view: %+v", view)
294		}
295	}
