501	func TestStateSurvivesReconnection(t *testing.T) {
502		store := testStore(t)
503		from, to := activeWindow()
504		id := uniqueID(t)
505		mustCreate(t, store, id, 100, from, to)
506		ctx := context.Background()
507		if _, _, err := store.CreateReservation(ctx, id, "res-1", 30); err != nil {
508			t.Fatalf("reserve: %v", err)
509		}
510		if _, err := store.SettleReservation(ctx, id, "res-1", ActionConfirm); err != nil {
511			t.Fatalf("confirm: %v", err)
512		}
513		if _, _, err := store.ReverseReservation(ctx, id, "res-1", "corr-1"); err != nil {
514			t.Fatalf("reverse: %v", err)
515		}
516	
517		// A fresh pool over the same database simulates a service restart.
518		pool, err := pgxpool.New(ctx, os.Getenv("TEST_DATABASE_URL"))
519		if err != nil {
520			t.Fatalf("reconnect: %v", err)
521		}
522		defer pool.Close()
523		restarted := NewStore(pool)
524		view, err := restarted.GetView(ctx, id)
525		if err != nil {
526			t.Fatalf("view after restart: %v", err)
527		}
528		if view.UsedAmount != 0 || view.AvailableAmount != 100 || len(view.Reservations) != 2 ||
529			view.Reservations[0].Status != StatusConfirmed || view.Reservations[1].Status != StatusReversed {
530			t.Fatalf("state lost across restart: %+v", view)
531		}
532		// The correction identifier is still replayed, not re-applied.
533		replay, created, err := restarted.ReverseReservation(ctx, id, "res-1", "corr-1")
534		if err != nil || created || replay.Amount != 30 {
535			t.Fatalf("reversal replay after restart: %+v created=%v err=%v", replay, created, err)
536		}
537	}
